/**
 * QuizLens AI - Background Service Worker (Manifest V3)
 * Supports Direct AI Calling (No Backend Needed) as well as Backend Proxy Mode
 */

import { DEFAULT_SETTINGS } from '../shared/constants';
import { ExtensionSettings, AnswerResult, ApiResponse, AnalyzeRequestPayload } from '../shared/types';
import { RuntimeMessage } from '../shared/messages';
import { solveWithGeminiDirect, solveWithGroqDirect, solveWithOpenRouterDirect } from './direct-ai';

// Initialize default settings and context menus on extension install
chrome.runtime.onInstalled.addListener(async () => {
  const existing = await chrome.storage.sync.get('settings');
  if (!existing || !existing.settings) {
    await chrome.storage.sync.set({ settings: DEFAULT_SETTINGS });
  }

  // Create right-click context menu
  try {
    chrome.contextMenus.create({
      id: 'quizlens-solve-selection',
      title: 'Giải bằng QuizLens AI',
      contexts: ['selection']
    });
  } catch (_) {}
});

// Handle context menu click
chrome.contextMenus.onClicked.addListener((info, tab) => {
  if (info.menuItemId === 'quizlens-solve-selection' && tab?.id) {
    chrome.tabs.sendMessage(tab.id, { type: 'TRIGGER_SELECTION_ANALYSIS' }).catch(() => {});
  }
});

/**
 * Retrieves current extension settings
 */
async function getSettings(): Promise<ExtensionSettings> {
  try {
    const data = await chrome.storage.sync.get('settings');
    return { ...DEFAULT_SETTINGS, ...(data.settings || {}) };
  } catch (e) {
    return DEFAULT_SETTINGS;
  }
}

/**
 * Saves extension settings
 */
async function saveSettings(newSettings: Partial<ExtensionSettings>): Promise<ExtensionSettings> {
  const current = await getSettings();
  const updated = { ...current, ...newSettings };
  await chrome.storage.sync.set({ settings: updated });
  return updated;
}

/**
 * Solves question directly from the client without any backend
 */
async function solveDirectly(payload: AnalyzeRequestPayload, settings: ExtensionSettings): Promise<AnswerResult> {
  const provider = payload.provider || settings.activeProvider;

  if (provider === 'gemini') {
    const key = payload.apiKey || settings.geminiApiKey;
    if (!key) throw new Error('NO_API_KEY');
    return solveWithGeminiDirect(payload.question, payload.options, key, payload.model || settings.geminiModel);
  }

  if (provider === 'groq') {
    const key = payload.apiKey || settings.groqApiKey;
    if (!key) throw new Error('NO_API_KEY');
    return solveWithGroqDirect(payload.question, payload.options, key, payload.model || settings.groqModel);
  }

  if (provider === 'openrouter') {
    const key = payload.apiKey || settings.openrouterApiKey;
    if (!key) throw new Error('NO_API_KEY');
    return solveWithOpenRouterDirect(payload.question, payload.options, key, payload.model || settings.openrouterModel);
  }

  throw new Error(`Nhà cung cấp AI không hợp lệ: ${provider}`);
}

/**
 * Makes API call to QuizLens Backend service if running
 */
async function solveWithBackend(payload: AnalyzeRequestPayload, settings: ExtensionSettings): Promise<AnswerResult> {
  const baseUrl = settings.backendUrl.replace(/\/+$/, '');
  const targetUrl = `${baseUrl}/api/v1/answer`;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 20000);

  const response = await fetch(targetUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      question: payload.question,
      options: payload.options,
      provider: payload.provider || settings.activeProvider,
      model: payload.model,
      apiKey: payload.apiKey
    }),
    signal: controller.signal
  });

  clearTimeout(timeoutId);

  if (!response.ok) {
    let errorMsg = `Lỗi máy chủ (${response.status})`;
    try {
      const errorJson = await response.json();
      if (errorJson.error?.message) errorMsg = errorJson.error.message;
    } catch (_) {}
    throw new Error(errorMsg);
  }

  const json = (await response.json()) as ApiResponse<AnswerResult>;
  if (!json.success || !json.data) {
    throw new Error(json.error?.message || 'Không có kết quả trả về từ Backend');
  }

  return json.data;
}

/**
 * Smart dispatcher: tries Direct Mode first if key is present,
 * otherwise tries Backend.
 */
async function handleAnalyzeQuestion(payload: AnalyzeRequestPayload, settings: ExtensionSettings): Promise<AnswerResult> {
  const activeKey =
    settings.activeProvider === 'gemini'
      ? settings.geminiApiKey
      : settings.activeProvider === 'groq'
      ? settings.groqApiKey
      : settings.openrouterApiKey;

  // 1. If user entered an API key, solve DIRECTLY (no backend needed!)
  if (activeKey && activeKey.trim().length > 0) {
    try {
      return await solveDirectly(payload, settings);
    } catch (directErr: any) {
      if (directErr.message !== 'NO_API_KEY') {
        throw directErr;
      }
    }
  }

  // 2. If no key, try backend server
  try {
    return await solveWithBackend(payload, settings);
  } catch (backendErr: any) {
    throw new Error(
      'Vui lòng bấm vào biểu tượng QuizLens AI trên thanh trình duyệt và nhập API Key (Gemini hoặc Groq) để bắt đầu sử dụng!'
    );
  }
}

// Runtime message listener
chrome.runtime.onMessage.addListener((message: RuntimeMessage, _sender, sendResponse) => {
  (async () => {
    try {
      switch (message.type) {
        case 'GET_SETTINGS': {
          const settings = await getSettings();
          sendResponse({ success: true, data: settings });
          break;
        }

        case 'SAVE_SETTINGS': {
          const updated = await saveSettings(message.payload);
          sendResponse({ success: true, data: updated });
          break;
        }

        case 'TEST_CONNECTION': {
          const settings = await getSettings();
          const activeKey =
            settings.activeProvider === 'gemini'
              ? settings.geminiApiKey
              : settings.activeProvider === 'groq'
              ? settings.groqApiKey
              : settings.openrouterApiKey;

          if (activeKey && activeKey.trim().length > 0) {
            sendResponse({ success: true, data: { mode: 'direct', message: 'API Key sẵn sàng hoạt động độc lập!' } });
          } else {
            // Test backend
            const baseUrl = settings.backendUrl.replace(/\/+$/, '');
            try {
              const res = await fetch(`${baseUrl}/api/v1/health`, { signal: AbortSignal.timeout(3000) });
              sendResponse({ success: res.ok, data: { mode: 'backend', connected: res.ok } });
            } catch (e) {
              sendResponse({ success: false, data: { mode: 'none' } });
            }
          }
          break;
        }

        case 'TEST_AI_KEY': {
          const { provider, model, apiKey } = message.payload;
          const dummyQuestion = 'Thủ đô của Việt Nam là gì?';
          const dummyOptions = { A: 'Hà Nội', B: 'TP.HCM' };
          let res: AnswerResult;
          if (provider === 'gemini') {
            res = await solveWithGeminiDirect(dummyQuestion, dummyOptions, apiKey, model);
          } else if (provider === 'groq') {
            res = await solveWithGroqDirect(dummyQuestion, dummyOptions, apiKey, model);
          } else {
            res = await solveWithOpenRouterDirect(dummyQuestion, dummyOptions, apiKey, model);
          }
          sendResponse({ success: true, data: res });
          break;
        }

        case 'ANALYZE_QUESTION': {
          const settings = await getSettings();
          const result = await handleAnalyzeQuestion(message.payload, settings);
          sendResponse({ success: true, data: result });
          break;
        }

        default:
          sendResponse({ success: false, error: 'Hành động không hợp lệ' });
      }
    } catch (error: any) {
      sendResponse({ success: false, error: error.message || 'Lỗi không xác định' });
    }
  })();

  return true;
});
